-- Automated BS calendar and attendance-linked payroll.
-- Calendar rows are deterministically generated by the CRM's bundled BS library,
-- validated again in PostgreSQL, and cached here for auditability.

alter table public.hr_payroll_items
  add column if not exists calendar_days smallint,
  add column if not exists eligible_calendar_days numeric(6,2),
  add column if not exists unpaid_units numeric(6,2) not null default 0,
  add column if not exists daily_rate numeric(14,6),
  add column if not exists salary_basis jsonb not null default '{}'::jsonb;

create table if not exists public.hr_attendance_exceptions(
  id uuid primary key default gen_random_uuid(),
  employee_id uuid not null references public.hr_employees(id) on delete cascade,
  attendance_date date not null,
  exception_type text not null check(exception_type in('MISSING_ATTENDANCE','MISSING_PUNCH_IN','MISSING_PUNCH_OUT')),
  status text not null default 'OPEN' check(status in('OPEN','RESOLVED','WAIVED')),
  details text,
  detected_at timestamptz not null default now(),
  resolved_at timestamptz,
  resolved_by uuid references public.staff_profiles(id),
  unique(employee_id,attendance_date,exception_type)
);

alter table public.hr_attendance_exceptions enable row level security;
drop policy if exists hr_attendance_exceptions_read on public.hr_attendance_exceptions;
create policy hr_attendance_exceptions_read on public.hr_attendance_exceptions for select to authenticated
using(public.has_permission('hr.view') or public.has_permission('payroll.view') or public.has_permission('payroll.manage'));

create or replace function public.hr_monthly_tds_from_approved_rules(monthly_taxable numeric,p_fiscal_year text)
returns numeric language plpgsql stable security definer set search_path=public as $$
declare rule_id uuid; annual_taxable numeric; annual_tax numeric;
begin
  select id into rule_id from hr_tax_rule_sets
  where fiscal_year=p_fiscal_year and status='ACTIVE' and approved_at is not null
  order by effective_from desc limit 1;
  if rule_id is null or coalesce(monthly_taxable,0)<=0 then return 0; end if;
  annual_taxable:=monthly_taxable*12;
  select coalesce(sum(greatest(least(annual_taxable,coalesce(upper_bound,annual_taxable))-lower_bound,0)*rate),0)
  into annual_tax from hr_tax_brackets where rule_set_id=rule_id and annual_taxable>lower_bound;
  return annual_tax/12;
end $$;

create or replace function public.hr_generate_bs_payroll(fiscal_year text,month_number integer,calculation_bs text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare
  p hr_attendance_periods%rowtype; profile hr_payroll_profiles%rowtype; settings hr_payroll_settings%rowtype;
  run_id uuid; existing_run hr_payroll_runs%rowtype; emp record; tax_rule_id uuid;
  calendar_day_count integer; eligible_days numeric; unpaid numeric; base_entitlement numeric; attendance_deduction_value numeric;
  period_salary numeric; base_pay numeric; allowance_total numeric; earning_total numeric; deduction_total numeric;
  gross_total numeric:=0; net_total numeric:=0; tax numeric; item_gross numeric; item_net numeric; employee_count integer:=0;
begin
  if not public.has_permission('payroll.prepare') and not public.has_permission('payroll.manage') then raise exception 'Payroll preparation permission required'; end if;
  select * into p from hr_attendance_periods ap where ap.bs_fiscal_year=hr_generate_bs_payroll.fiscal_year and ap.bs_month=hr_generate_bs_payroll.month_number and ap.status='LOCKED';
  if not found then raise exception 'Attendance must be complete and locked before payroll generation'; end if;
  select * into existing_run from hr_payroll_runs where period_start=p.period_start and period_end=p.period_end;
  if found then raise exception 'Payroll already exists for this BS month with status %. Existing runs are never overwritten.',existing_run.status; end if;
  select * into profile from hr_payroll_profiles where code='AECS_NEPAL_OFFICE' and is_active;
  select * into settings from hr_payroll_settings where profile_id=profile.id;
  if settings.profile_id is null then raise exception 'AECS payroll settings are incomplete'; end if;
  select count(*) into calendar_day_count from hr_bs_calendar c where c.bs_fiscal_year=hr_generate_bs_payroll.fiscal_year and c.bs_month=hr_generate_bs_payroll.month_number;
  if calendar_day_count not between 29 and 32 then raise exception 'The BS month must contain 29 to 32 validated calendar days'; end if;
  select tr.id into tax_rule_id from hr_tax_rule_sets tr where tr.fiscal_year=hr_generate_bs_payroll.fiscal_year and tr.status='ACTIVE' and tr.approved_at is not null order by tr.effective_from desc limit 1;
  if settings.tds_status='ACTIVE' and tax_rule_id is null then raise exception 'Activate an approved tax rule set for fiscal year % before running payroll',fiscal_year; end if;

  insert into hr_payroll_runs(period_start,period_end,status,prepared_by,bs_fiscal_year,bs_month,calculation_bs_date,rule_snapshot)
  values(p.period_start,p.period_end,'DRAFT',auth.uid(),fiscal_year,month_number,calculation_bs,
    jsonb_build_object('profile',profile.code,'version',settings.version,'salary_divisor','ACTUAL_BS_CALENDAR_DAYS','calendar_days',calendar_day_count,'tax_rule_set_id',tax_rule_id,'late_deduction',false,'rounding','FINAL_COMPONENTS_ONLY'))
  returning id into run_id;

  for emp in
    select * from hr_employees where payroll_eligible and payroll_profile_id=profile.id
      and join_date<=p.period_end and (exit_date is null or exit_date>=p.period_start)
      and employment_status in('ACTIVE','ON_LEAVE','PROBATION','EXITED')
  loop
    select coalesce((select h.new_basic from hr_salary_history h where h.employee_id=emp.id and h.effective_from<=p.period_end order by h.effective_from desc,h.created_at desc limit 1),emp.base_salary)
      into period_salary;
    select count(*)::numeric,
      coalesce(sum(coalesce((select h.new_basic from hr_salary_history h where h.employee_id=emp.id and h.effective_from<=d::date order by h.effective_from desc,h.created_at desc limit 1),emp.base_salary)/calendar_day_count),0)
      into eligible_days,base_entitlement
    from generate_series(greatest(p.period_start,emp.join_date),least(p.period_end,coalesce(emp.exit_date,p.period_end)),interval '1 day') d;

    select coalesce(sum(x.unpaid_unit),0),
      coalesce(sum(x.unpaid_unit*coalesce((select h.new_basic from hr_salary_history h where h.employee_id=emp.id and h.effective_from<=x.attendance_date order by h.effective_from desc,h.created_at desc limit 1),emp.base_salary)/calendar_day_count),0)
      into unpaid,attendance_deduction_value
    from (
      select a.attendance_date,case a.status
        when 'HALF_DAY' then .5
        when 'UNPAID_LEAVE' then coalesce((select case when l.from_date=l.to_date then l.day_fraction else 1 end from hr_leave_requests l where l.employee_id=emp.id and l.status='APPROVED' and a.attendance_date between l.from_date and l.to_date order by l.approved_at desc limit 1),1)
        when 'ABSENT' then 1 else 0 end as unpaid_unit
      from hr_attendance a join hr_bs_calendar c on c.ad_date=a.attendance_date
      where a.employee_id=emp.id and a.attendance_date between greatest(p.period_start,emp.join_date) and least(p.period_end,coalesce(emp.exit_date,p.period_end))
        and c.bs_fiscal_year=hr_generate_bs_payroll.fiscal_year and c.bs_month=hr_generate_bs_payroll.month_number and c.day_type='WORKING_DAY'
    ) x;

    base_pay:=round(greatest(base_entitlement-attendance_deduction_value,0),settings.calculation_precision);
    select coalesce(sum(amount),0) into allowance_total from hr_salary_components where employee_id=emp.id and component_type='ALLOWANCE' and effective_from<=p.period_end and (effective_to is null or effective_to>=p.period_start);
    select coalesce(sum(amount),0) into earning_total from hr_salary_components where employee_id=emp.id and component_type='COMMISSION' and effective_from<=p.period_end and (effective_to is null or effective_to>=p.period_start);
    select coalesce(sum(case when adjustment_type='DEDUCTION' then amount else 0 end),0),coalesce(sum(case when adjustment_type<>'DEDUCTION' then amount else 0 end),0)
      into deduction_total,item_gross from hr_payroll_adjustments pa where pa.employee_id=emp.id and pa.bs_fiscal_year=hr_generate_bs_payroll.fiscal_year and pa.bs_month=hr_generate_bs_payroll.month_number and pa.status='APPROVED';
    earning_total:=earning_total+item_gross;
    item_gross:=base_pay+allowance_total+earning_total;
    tax:=round(public.hr_monthly_tds_from_approved_rules(item_gross,fiscal_year),settings.calculation_precision);
    item_net:=round(item_gross-tax-deduction_total,settings.payment_rounding);
    insert into hr_payroll_items(payroll_run_id,employee_id,basic_salary,monthly_base_salary,scheduled_working_days,payable_days,non_payable_days,attendance_deduction,allowance,commission,ssf_deduction,cit_deduction,tds_tax,other_deduction,calendar_days,eligible_calendar_days,unpaid_units,daily_rate,salary_basis)
    values(run_id,emp.id,base_pay,period_salary,calendar_day_count,greatest(eligible_days-unpaid,0),unpaid,round(attendance_deduction_value,settings.calculation_precision),allowance_total,earning_total,0,0,tax,deduction_total,calendar_day_count,eligible_days,unpaid,period_salary/calendar_day_count,
      jsonb_build_object('monthly_basic_at_period_end',period_salary,'eligible_calendar_days',eligible_days,'unpaid_units',unpaid,'unrounded_entitlement',base_entitlement,'unrounded_attendance_deduction',attendance_deduction_value));
    update hr_payroll_adjustments pa set status='APPLIED',payroll_run_id=run_id where pa.employee_id=emp.id and pa.bs_fiscal_year=hr_generate_bs_payroll.fiscal_year and pa.bs_month=hr_generate_bs_payroll.month_number and pa.status='APPROVED';
    employee_count:=employee_count+1; gross_total:=gross_total+item_gross; net_total:=net_total+item_net;
  end loop;
  insert into hr_payroll_approval_log(payroll_run_id,from_status,to_status,acted_by,note)
  values(run_id,null,'DRAFT',auth.uid(),'Generated automatically from the validated BS calendar, confirmed attendance, approved leave, and effective salary history');
  return jsonb_build_object('run_id',run_id,'employee_count',employee_count,'gross_total',round(gross_total,2),'net_total',round(net_total,2),'status','DRAFT','calendar_days',calendar_day_count);
end $$;

create or replace function public.hr_run_automated_bs_payroll(calendar_payload jsonb,fiscal_year text,month_number integer,calculation_bs text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare
  row_count integer; first_date date; last_date date; bs_year text; invalid_count integer;
  pending_corrections integer; pending_leaves integer; open_exceptions integer; result jsonb;
begin
  if not public.has_permission('payroll.prepare') and not public.has_permission('payroll.manage') then raise exception 'Payroll preparation permission required'; end if;
  if jsonb_typeof(calendar_payload)<>'array' or month_number not between 1 and 12 then raise exception 'Invalid BS calendar payload'; end if;
  select count(*),min(x.ad_date),max(x.ad_date),min(split_part(x.bs_date,'-',1))
    into row_count,first_date,last_date,bs_year
  from jsonb_to_recordset(calendar_payload) as x(ad_date date,bs_date text,bs_day integer,day_type text);
  if row_count not between 29 and 32 then raise exception 'A BS month must contain 29 to 32 days'; end if;
  select count(*) into invalid_count from jsonb_to_recordset(calendar_payload) as x(ad_date date,bs_date text,bs_day integer,day_type text)
  where x.bs_date<>bs_year||'-'||lpad(month_number::text,2,'0')||'-'||lpad(x.bs_day::text,2,'0')
    or x.bs_day not between 1 and row_count or x.day_type not in('WORKING_DAY','WEEKLY_OFF')
    or x.ad_date<>(first_date+(x.bs_day-1));
  if invalid_count>0 then raise exception 'The generated BS calendar failed validation'; end if;
  if last_date>(now() at time zone 'Asia/Kathmandu')::date then raise exception 'Payroll can run only after the selected BS month has ended'; end if;

  insert into hr_bs_calendar(ad_date,bs_date,bs_fiscal_year,bs_month,bs_day,day_type,calendar_status,approved_by,approved_at)
  select x.ad_date,x.bs_date,fiscal_year,month_number,x.bs_day,x.day_type,'ACTIVE',auth.uid(),now()
  from jsonb_to_recordset(calendar_payload) as x(ad_date date,bs_date text,bs_day integer,day_type text)
  on conflict(ad_date) do update set bs_date=excluded.bs_date,bs_fiscal_year=excluded.bs_fiscal_year,bs_month=excluded.bs_month,bs_day=excluded.bs_day,
    day_type=case when hr_bs_calendar.day_type='HOLIDAY' then 'HOLIDAY' else excluded.day_type end,
    holiday_name=case when hr_bs_calendar.day_type='HOLIDAY' then hr_bs_calendar.holiday_name else null end,
    calendar_status='ACTIVE',approved_by=auth.uid(),approved_at=now();

  update hr_attendance_exceptions ex set status='RESOLVED',resolved_at=now(),resolved_by=auth.uid()
  where ex.status='OPEN' and ex.attendance_date between first_date and last_date and exists(
    select 1 from hr_attendance a where a.employee_id=ex.employee_id and a.attendance_date=ex.attendance_date
      and (a.status not in('PRESENT','LATE','HALF_DAY') or (a.clock_in is not null and a.clock_out is not null))
  );

  insert into hr_attendance_exceptions(employee_id,attendance_date,exception_type,details)
  select e.id,c.ad_date,
    case when a.id is null then 'MISSING_ATTENDANCE' when a.clock_in is null then 'MISSING_PUNCH_IN' else 'MISSING_PUNCH_OUT' end,
    case when a.id is null then 'No attendance, approved leave, or confirmed absence was recorded' when a.clock_in is null then 'Attendance has no punch-in time' else 'Attendance has no punch-out time' end
  from hr_employees e join hr_bs_calendar c on c.ad_date between greatest(first_date,e.join_date) and least(last_date,coalesce(e.exit_date,last_date)) and c.day_type='WORKING_DAY'
  left join hr_attendance a on a.employee_id=e.id and a.attendance_date=c.ad_date
  where e.payroll_eligible and e.payroll_profile_id=(select id from hr_payroll_profiles where code='AECS_NEPAL_OFFICE' and is_active)
    and e.employment_status in('ACTIVE','ON_LEAVE','PROBATION','EXITED')
    and (a.id is null or (a.status in('PRESENT','LATE','HALF_DAY') and (a.clock_in is null or a.clock_out is null)))
  on conflict(employee_id,attendance_date,exception_type) do update set status='OPEN',details=excluded.details,detected_at=now(),resolved_at=null,resolved_by=null;

  select count(*) into pending_corrections from hr_attendance_corrections where status='PENDING' and attendance_date between first_date and last_date;
  select count(*) into pending_leaves from hr_leave_requests where status='PENDING' and daterange(from_date,to_date,'[]')&&daterange(first_date,last_date,'[]');
  select count(*) into open_exceptions from hr_attendance_exceptions where status='OPEN' and attendance_date between first_date and last_date;
  if pending_corrections+pending_leaves+open_exceptions>0 then
    insert into hr_attendance_periods(bs_fiscal_year,bs_month,period_start,period_end,status,remarks)
    values(fiscal_year,month_number,first_date,last_date,'READY_TO_CLOSE','Payroll blocked until attendance and leave exceptions are resolved')
    on conflict(bs_fiscal_year,bs_month) do update set period_start=excluded.period_start,period_end=excluded.period_end,status='READY_TO_CLOSE',closed_by=null,closed_at=null,remarks=excluded.remarks;
    return jsonb_build_object('status','BLOCKED','blocking_count',pending_corrections+pending_leaves+open_exceptions,
      'message',format('Payroll is blocked: %s attendance exception(s), %s pending correction(s), and %s pending leave request(s) must be resolved.',open_exceptions,pending_corrections,pending_leaves));
  end if;

  insert into hr_attendance_periods(bs_fiscal_year,bs_month,period_start,period_end,status,closed_by,closed_at,remarks)
  values(fiscal_year,month_number,first_date,last_date,'LOCKED',auth.uid(),now(),'Automatically validated and locked when payroll was run')
  on conflict(bs_fiscal_year,bs_month) do update set period_start=excluded.period_start,period_end=excluded.period_end,status='LOCKED',closed_by=auth.uid(),closed_at=now(),remarks=excluded.remarks;
  result:=public.hr_generate_bs_payroll(fiscal_year,month_number,calculation_bs);
  return result;
end $$;

create or replace function public.hr_guard_payroll_finalization()
returns trigger language plpgsql security definer set search_path=public as $$
declare blockers integer;
begin
  if new.status='FINALIZED' and old.status is distinct from 'FINALIZED' then
    select
      (select count(*) from hr_attendance_exceptions where status='OPEN' and attendance_date between new.period_start and new.period_end)
      +(select count(*) from hr_attendance_corrections where status='PENDING' and attendance_date between new.period_start and new.period_end)
      +(select count(*) from hr_leave_requests where status='PENDING' and daterange(from_date,to_date,'[]')&&daterange(new.period_start,new.period_end,'[]'))
    into blockers;
    if blockers>0 then raise exception 'Payroll cannot be finalized while % attendance or leave item(s) remain unresolved',blockers; end if;
  end if;
  return new;
end $$;

drop trigger if exists hr_payroll_finalization_guard on public.hr_payroll_runs;
create trigger hr_payroll_finalization_guard before update of status on public.hr_payroll_runs
for each row execute function public.hr_guard_payroll_finalization();

revoke all on function public.hr_monthly_tds_from_approved_rules(numeric,text),public.hr_run_automated_bs_payroll(jsonb,text,integer,text),public.hr_guard_payroll_finalization() from public;
grant execute on function public.hr_run_automated_bs_payroll(jsonb,text,integer,text) to authenticated;

